  ('course-play-sindico-alta-performance', 'sindico-alta-performance', 'Síndico Alta Performance', null, 'Aplique práticas de liderança e estratégias que garantem resultados eficientes para seu condomínio.', '/dev-server/src/assets/cursos/play/sindico-alta-performance.webp', '/dev-server/src/assets/cursos/play/sindico-alta-performance.webp', 'SíndicoLab', null, null, null, 'cat-sindico-carreira', '11111111-1111-1111-1111-111111111111', 'exclusive', 'published', 'external_checkout', null, 'https://pay.kiwify.com.br/lTGYaNe', 349, 'Certificado · 90 dias de acesso', false, false, '2026-05-25T20:18:52.410Z', '2026-09-12T20:18:52.410Z'),
