  ('course-play-como-captar-mais-clientes', 'como-captar-mais-clientes', 'Como Captar Mais Clientes', null, 'Aprenda estratégias de captação e técnicas de networking para expandir sua carteira de clientes e consolidar-se como referência.', '/dev-server/src/assets/cursos/play/captar-mais-clientes.webp', '/dev-server/src/assets/cursos/play/captar-mais-clientes.webp', 'SíndicoLab', null, null, null, 'cat-sindico-carreira', '11111111-1111-1111-1111-111111111111', 'exclusive', 'published', 'external_checkout', null, 'https://pay.kiwify.com.br/s0Z3UNQ', 500, 'Certificado · 90 dias de acesso', false, false, '2026-06-03T20:18:52.410Z', '2026-09-12T20:18:52.410Z'),
