  ('evt-1', 'Workshop de Inteligência Artificial para síndicos', 'workshop-ia-para-sindicos', 'Uma tarde prática de automação e IA aplicada à rotina do síndico profissional.', 'Encontro presencial com demonstrações reais de automação de comunicados, atas, cobranças e atendimento a moradores. Traga seu notebook: você sai com fluxos prontos.', null, '2026-10-16T20:18:52.412Z', '14h às 18h', '2026-10-16T20:18:52.412Z', 'Studio Marqo — São Paulo/SP', 'presencial', 'São Paulo', 'https://www.sympla.com.br/sindicolab', 'https://www.sympla.com.br/sindicolab', 'published', true, '2026-09-02T20:18:52.412Z', '2026-09-20T20:18:52.412Z'),
  ('evt-2', 'Live: prestação de contas sem ruído', 'live-prestacao-de-contas', 'Como apresentar números para o condomínio sem gerar desconfiança.', 'Transmissão aberta com um roteiro de apresentação de contas, os erros mais comuns e como responder às perguntas difíceis da assembleia.', null, '2026-10-01T20:18:52.412Z', '19h30', '2026-10-01T20:18:52.412Z', 'Online — YouTube SíndicoLab', 'online', null, 'https://www.youtube.com/@SindicoLab/videos', null, 'published', false, '2026-09-10T20:18:52.412Z', '2026-09-19T20:18:52.412Z'),
