insert into public.portal_posts (id, title, slug, excerpt, content, cover_image, category_id, author_id, featured, published, published_at, view_count, cover_alt, seo_title, meta_description, social_image_url) values
  ('ppost-nova-lei', 'Nova lei das assembleias virtuais: o que muda para condomínios', 'nova-lei-das-assembleias-virtuais', 'Entenda os principais pontos da Lei 14.309/2022 e os impactos na gestão, participação e segurança jurídica das deliberações.', '<p>A <strong>Lei 14.309/2022</strong> trouxe mudanças importantes para as assembleias condominiais realizadas por meio digital. O texto regulamenta a convocação, a participação dos condôminos e a validade das votações.</p><p>Entre os principais pontos estão a necessidade de identificação do participante, a gravação da sessão e a possibilidade de voto por correspondência eletrônica, desde que previsto em convenção ou regulamento.</p><p>Para os síndicos, a lei representa mais agilidade, mas também exige cuidado com a segurança da informação e a guarda dos registros.</p>', '/dev-server/src/assets/portal/portal-cover-2.jpg', 'pcat-direito', 'pa-ricardo-freitas', true, true, '2026-08-10T17:21:58.000Z', 2450, 'Edifícios residenciais vistos de baixo', 'Nova lei das assembleias virtuais: o que muda para condomínios', 'Entenda os principais pontos da Lei 14.309/2022 e os impactos na gestão, participação e segurança jurídica das deliberações.', '/dev-server/src/assets/portal/portal-cover-2.jpg'),
  ('ppost-inadimplencia', 'Inadimplência recua pelo 3º mês seguido, aponta índice nacional', 'inadimplencia-recua-terceiro-mes', 'Dados do índice nacional mostram queda consistente da inadimplência em condomínios, sinalizando recuperação do setor.', '<p>O índice nacional de inadimplência condominial registrou queda pelo terceiro mês consecutivo. Especialistas apontam que a melhora está relacionada à retomada econômica e ao uso de ferramentas de cobrança mais eficientes.</p><p>Síndicos e administradoras destacam a importância da negociação preventiva e da transparência nas finanças do condomínio.</p>', '/dev-server/src/assets/portal/portal-cover-5.jpg', 'pcat-mercado', 'pa-camila-santos', false, true, '2026-08-09T17:21:58.000Z', 1830, 'Análise de indicadores financeiros', 'Inadimplência recua pelo 3º mês seguido, aponta índice nacional', 'Dados do índice nacional mostram queda consistente da inadimplência em condomínios, sinalizando recuperação do setor.', '/dev-server/src/assets/portal/portal-cover-5.jpg'),
  ('ppost-elevadores', 'Elevadores: manutenção preventiva reduz falhas e custos em até 30%', 'manutencao-preventiva-elevadores', 'Um cronograma de manutenção preventiva bem estruturado pode reduzir drasticamente as paradas e os gastos com reparos emergenciais.', '<p>A manutenção preventiva de elevadores é um investimento que se paga rapidamente. Segundo especialistas, condomínios que adotam revisões periódicas registram queda de até 30% nos custos de reparo.</p><p>O ideal é contar com uma empresa credenciada e manter um laudo técnico atualizado, conforme exigido pela legislação de segurança.</p>', '/dev-server/src/assets/portal/portal-cover-1.jpg', 'pcat-manutencao', 'pa-juliana-duarte', false, true, '2026-08-08T17:21:58.000Z', 1520, 'Profissional revisando um plano de manutenção', 'Elevadores: manutenção preventiva reduz falhas e custos em até 30%', 'Um cronograma de manutenção preventiva bem estruturado pode reduzir drasticamente as paradas e os gastos com reparos emergenciais.', '/dev-server/src/assets/portal/portal-cover-1.jpg'),
  ('ppost-convivencia', 'Como melhorar a convivência entre moradores e evitar conflitos frequentes', 'convivencia-entre-moradores', 'Pequenas ações de comunicação e respeito às regras comuns podem transformar o clima do condomínio.', '<p>A convivência em condomínios pode ser desafiadora, mas regras claras e comunicação transparente ajudam a evitar atritos. Especialistas recomendam assembleias participativas, canais de ouvidoria e mediação de conflitos.</p><p>O síndico desempenha papel central como mediador, mas a responsabilidade pela boa convivência é coletiva.</p>', '/dev-server/src/assets/portal/portal-cover-4.jpg', 'pcat-moradores', 'pa-camila-santos', false, true, '2026-08-07T17:21:58.000Z', 980, 'Moradores reunidos em um ambiente de convivência', 'Como melhorar a convivência entre moradores e evitar conflitos frequentes', 'Pequenas ações de comunicação e respeito às regras comuns podem transformar o clima do condomínio.', '/dev-server/src/assets/portal/portal-cover-4.jpg'),
  ('ppost-checklist', 'Checklist mensal do síndico: 15 tarefas que não podem faltar', 'checklist-mensal-do-sindico', 'Organize a rotina da gestão condominial com um checklist prático de atenção mensal.', '<p>Síndicos profissionais e voluntários podem se beneficiar de um checklist mensal para não perder prazos. Entre as tarefas estão aprovação de despesas, acompanhamento de inadimplência, revisão de contratos e inspeção das áreas comuns.</p><p>A disciplina na rotina evita surpresas e melhora a previsibilidade financeira do condomínio.</p>', '/dev-server/src/assets/portal/portal-cover-1.jpg', 'pcat-sindicos', 'pa-juliana-duarte', false, true, '2026-08-06T17:21:58.000Z', 875, 'Checklist de gestão sobre uma mesa', 'Checklist mensal do síndico: 15 tarefas que não podem faltar', 'Organize a rotina da gestão condominial com um checklist prático de atenção mensal.', '/dev-server/src/assets/portal/portal-cover-1.jpg'),
  ('ppost-energia', 'Contas de luz em áreas comuns: como reduzir sem perder conforto', 'reduzir-contas-luz-areas-comuns', 'Economia de energia nas áreas comuns é possível com iluminação LED, sensores de presença e conscientização dos moradores.', '<p>A conta de luz é uma das maiores despesas operacionais dos condomínios. Substituir lâmpadas por LED, instalar sensores de presença e fazer manutenção periódica do sistema elétrico são medidas simples e eficazes.</p><p>Além da economia, essas ações aumentam a sustentabilidade do empreendimento.</p>', '/dev-server/src/assets/portal/portal-cover-3.jpg', 'pcat-noticias', 'pa-camila-santos', false, true, '2026-08-05T17:21:58.000Z', 720, 'Área comum iluminada de um condomínio', 'Contas de luz em áreas comuns: como reduzir sem perder conforto', 'Economia de energia nas áreas comuns é possível com iluminação LED, sensores de presença e conscientização dos moradores.', '/dev-server/src/assets/portal/portal-cover-3.jpg')
